#!/usr/bin/env python3
"""Offline finite-domain network rule mining service.

Reads one JSON request on stdin, writes one JSON response on stdout, exits 0.
Implements the contract described in the task statement using only the
Python standard library.
"""
import json
import re
import sys
from fractions import Fraction

MAX_INPUT_BYTES = 8388608
MAX_DEPTH = 64
MAX_TRACES = 128
MAX_ROWS = 16384
MAX_TRAIN_CTX = 4096
MAX_PROBE_CTX = 128
MAX_QUERY_CTX = 1024
MAX_TRAIN_SOURCES = 16

NUMERIC_TYPES = ("TIME", "SIZE", "COUNT")
ALL_TYPES = ("TIME", "SIZE", "COUNT", "ID", "FLAG")
CMP_OPS = {"eq": "==", "ne": "!=", "lt": "<", "le": "<=", "gt": ">", "ge": ">="}
EQ_OPS = ("eq", "ne")
AGG_OPS = ("sum", "mean", "min", "max")

RE_NAME = re.compile(r"[a-z][a-z0-9_]{0,31}\Z")
RE_IDVAL = re.compile(r"[A-Za-z0-9_.:\-]{1,32}\Z")
RE_TID = re.compile(r"[A-Za-z][A-Za-z0-9_\-]{0,31}\Z")

I32_LO = -(2 ** 31)
I32_HI = 2 ** 31 - 1


class ServiceError(Exception):
    def __init__(self, code):
        Exception.__init__(self, code)
        self.code = code


def die(code):
    raise ServiceError(code)


# --------------------------------------------------------------------------
# small type helpers (JSON booleans are never integers in this contract)
# --------------------------------------------------------------------------
def is_int(v):
    return type(v) is int


def is_bool(v):
    return type(v) is bool


def is_str(v):
    return type(v) is str


def is_i32(v):
    return type(v) is int and I32_LO <= v <= I32_HI


# --------------------------------------------------------------------------
# JSON front end
# --------------------------------------------------------------------------
def _bad_constant(_name):
    die("E_JSON")


def _parse_float(text):
    try:
        val = float(text)
    except ValueError:
        die("E_JSON")
    if val != val or val in (float("inf"), float("-inf")):
        die("E_JSON")
    return val


def _object_hook(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            die("E_JSON")
        out[key] = value
    return out


def check_depth(obj):
    """Container nesting depth; root container has depth 1."""
    if not isinstance(obj, (dict, list)):
        return
    stack = [(obj, 1)]
    while stack:
        node, depth = stack.pop()
        if depth > MAX_DEPTH:
            die("E_JSON")
        child_depth = depth + 1
        if isinstance(node, dict):
            for value in node.values():
                if isinstance(value, (dict, list)):
                    stack.append((value, child_depth))
        else:
            for value in node:
                if isinstance(value, (dict, list)):
                    stack.append((value, child_depth))


def parse_request(raw):
    if len(raw) > MAX_INPUT_BYTES:
        die("E_LIMIT")
    if raw.startswith(b"\xef\xbb\xbf"):
        die("E_JSON")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        die("E_JSON")
    try:
        obj = json.loads(text, object_pairs_hook=_object_hook,
                         parse_constant=_bad_constant, parse_float=_parse_float)
    except ServiceError:
        raise
    except RecursionError:
        die("E_JSON")
    except ValueError:
        die("E_JSON")
    check_depth(obj)
    return obj


